def nav(active='Plany'):
 return '<nav class="bottomnav" aria-label="Nawigacja">'+''.join(f'<button class="{"active" if name==active else ""}" data-go="{go}">{ico(ic)}{name}</button>' for name,ic,go in [('Trening','workout','workout'),('Plany','plans','plans'),('Historia','history','history'),('Postęp','progress','progress'),('Profil','profile','profile')])+'</nav>'
def header(back=False, label='Fundament siły'):
 left=f'<button class="backbtn" data-go="plan">{ico("back")}<span>{label}</span></button>' if back else '<span class="brand">forma<span>.</span></span>'
 return '<div class="status"><span>9:41</span><svg viewBox="0 0 50 14" aria-hidden="true"><path fill="currentColor" d="M0 9h3v4H0zm5-3h3v7H5zm5-3h3v10h-3zm5-3h3v13h-3z"/><rect x="26" y="2" width="21" height="10" rx="2" stroke="currentColor" fill="none"/><rect x="28" y="4" width="16" height="6" rx="1" fill="currentColor"/><path d="M49 5v4" stroke="currentColor"/></svg></div><header class="appbar">'+left+f'<button class="iconbtn" data-go="plans" aria-label="Wróć do planów">{ico("plans")}</button>'+'</header>'
def tabs(session):
 return f'<div class="tabs" role="group" aria-label="Wybór treningu"><button data-session="a" class="{"on" if session=="a" else ""}" aria-pressed="{str(session=="a").lower()}">Trening A</button><button data-session="b" class="{"on" if session=="b" else ""}" aria-pressed="{str(session=="b").lower()}">Trening B</button></div>'
def source(ex=None):
 ex=ex or A[0]
 return '<details class="source"><summary>Oryginalny zapis i źródło</summary><p>Materiał syntetyczny: '+ex['name']+' · '+ex['sets']+' · '+ex['load']+' · '+ex['rest']+'. Przypis przykładowy: plan A/B, strona 1.</p></details>'

def sets_table(ex=None):
 ex=ex or A[0]
 count=4 if ex is A[0] else 3
 rep='45 s' if ex['icon']=='plank' else ('8–10' if ex['icon']=='row' else ('5' if ex['icon'] in ['dead','bench'] else ('8' if ex['icon']=='press' else '6')))
 rows=''
 for n in range(1,count+1):
  load=(str([80,85,90][n-1])+' kg') if ex['icon']=='dead' else ex['load']
  if ex['icon']=='row': load+=' / ręka'
  label=str(n)+(' · opcj.' if ex['icon']=='pull' and n==3 else '')
  rows+=f'<tr><td>{label}</td><td>{rep}</td><td>{load}</td><td>{ex["rest"]}</td></tr>'
 return '<table class="series"><caption>Serie w planie</caption><thead><tr><th scope="col">Seria</th><th scope="col">'+('Czas' if ex['icon']=='plank' else 'Powt.')+'</th><th scope="col">Obciążenie</th><th scope="col">Przerwa</th></tr></thead><tbody>'+rows+'</tbody></table>'

def detail_inset(ex=None):
 return '<div class="inline-detail">'+sets_table(ex)+'<div class="note"><strong>Wskazówka z planu</strong>Utrzymaj kontrolowany ruch i jednakowe tempo w każdej serii.</div>'+source(ex)+'</div>'
def exercise(ex,variant,i,expanded=False):
 thumb=f'<span class="thumb">{exicon(ex["icon"])}</span>'
 meta=ex['intensity']
 optional=' <span class="pill optional">Opcjonalna 3. seria</span>' if ex['icon']=='pull' else ''
 name=f'<span class="ename"><strong>{ex["name"]}</strong><small>{meta}</small></span>'
 action=('data-expand aria-expanded="'+str(expanded).lower()+'"') if variant=='table' else 'data-go="detail"'
 btn=f'<button class="exercise-top" {action} aria-label="Szczegóły: {ex["name"]}" data-exercise="{i}">{thumb}{name}{ico("down" if variant=="table" else "chevron","chev")}</button>'
 metrics='<div class="metrics">'+''.join(f'<div><small>{label}</small><strong class="{"long" if len(value)>9 else ""}">{value}</strong></div>' for label,value in [('Serie × powt.',ex['sets']),('Obciążenie',ex['load']),('Przerwa',ex['rest'])])+'</div>'
 return f'<article class="exercise">{btn}{metrics}'+(detail_inset(ex) if expanded else '')+'</article>'
def plans(variant,session):
 featured='<section class="planblock"><h2>Fundament siły</h2><p>Plan A/B</p><div class="planmeta">2 treningi · 8 ćwiczeń</div><button class="btn light" data-go="plan">Otwórz plan '+ico('chevron')+'</button></section>'
 rows=''.join(f'<button class="dayrow" data-session="{s}" data-go="plan"><span class="dayletter">{s.upper()}</span><span class="daycopy"><strong>{title}</strong><small>4 ćwiczenia · {detail}</small></span>{ico("chevron","chev")}</button>' for s,title,detail in [('a','Siła podstawowa','nogi, klatka, plecy'),('b','Siła i akcesoria','tył ciała, barki, core')])
 if variant=='table':
  body='<div class="headline"><div><h1>Twoje plany</h1><p class="sub">Wybierz plan lub konkretny trening.</p></div></div>'+featured+'<h2>Treningi w planie</h2>'+rows
 elif variant=='cards':
  body='<div class="headline"><h1>Twoje plany</h1><button class="iconbtn" data-info="Nowy plan pozostaje poza interakcjami mock-upu." aria-label="Nowy plan">'+ico('plus')+'</button></div>'+featured+'<div class="sectionhead"><h2>Wybierz trening</h2></div>'+rows
 else:
  body='<div class="headline"><div><h1>Twoje plany</h1><p class="sub">Twój plan, gotowy do otwarcia.</p></div></div>'+featured+'<div class="sectionhead"><h2>W tym planie</h2></div>'+rows
 return body+'<div class="split-actions"><button class="btn secondary" data-info="Import: istniejący przepływ pozostaje bez zmian.">'+ico('upload')+' Importuj</button><button class="btn secondary" data-info="Tworzenie planu: istniejący edytor pozostaje bez zmian.">'+ico('plus')+' Nowy plan</button></div>'
def plan(variant,session,expand=False):
 data=A if session=='a' else B
 title='<div class="headline" style="margin-bottom:0"><div><h1>Fundament siły</h1><p class="sub plan-version">Plan A/B · aktualna wersja</p></div><button class="iconbtn" data-info="Edycja planu pozostaje w obecnym edytorze." aria-label="Edytuj plan">'+ico('edit')+'</button></div>'+tabs(session)
 if variant=='cards': title='<div class="topband">'+title+'</div>'
 count='12 serii + 1 opcjonalna' if session=='a' else '12 serii'
 title+=f'<div class="sectionhead"><h2>{"Siła podstawowa" if session=="a" else "Siła i akcesoria"}</h2><span>4 ćwiczenia</span></div><p class="sub plan-count" style="margin:0 0 14px">{count}</p>'
 if variant=='table': title+='<div class="tablehead"><span>Serie × powt.</span><span>Obciążenie</span><span>Przerwa</span></div>'
 return title+''.join(exercise(ex,variant,i,expand and i==0) for i,ex in enumerate(data))+'<button class="textbtn" data-info="Cały plan zawiera trening A i B. Przełącz trening u góry.">Cały plan i wersje '+ico('down')+'</button>'
def details(variant,session,eidx=0):
 data=A if session=='a' else B
 ex=data[eidx]
 title='<div class="detailtitle"><span class="thumb">'+exicon(ex['icon'])+'</span><div><h1>'+ex['name']+'</h1><p class="sub">Trening '+session.upper()+' · '+ex['group']+'</p></div></div>'
 facts='<div class="facts"><div><strong>'+ex['sets']+'</strong><small>'+('Serie × czas' if ex['icon']=='plank' else 'Serie × powt.')+'</small></div><div><strong class="'+('compactvalue' if len(ex['load'])>6 else '')+'">'+ex['load']+'</strong><small>'+ex['intensity']+'</small></div><div><strong class="mid">'+ex['rest']+'</strong><small>Przerwa</small></div></div>'
 note='<div class="note"><strong>Wskazówka z planu</strong>Utrzymaj kontrolowany ruch i jednakowe tempo w każdej serii.</div>'
 if variant=='table':
  return '<div class="headline" style="margin-bottom:0"><h1>Fundament siły</h1></div>'+tabs(session)+'<p class="sub" style="margin-bottom:12px">Trening '+session.upper()+' · szczegóły w miejscu</p>'+''.join(exercise(e,variant,i,i==eidx) for i,e in enumerate(data))
 content=sets_table(ex)+note+source(ex)
 if variant=='cards': return title+facts+'<section class="sheet"><div class="handle" aria-hidden="true"></div>'+content+'</section>'
 return title+facts+content

def workout(variant,session="a"):
 title='<div class="stepnav"><strong>Trening A · ćwiczenie 1 z 4</strong><button class="iconbtn" data-go="plan" aria-label="Przegląd ćwiczeń">'+ico('plans')+'</button></div><h1>Przysiad ze sztangą</h1><p class="sub">Seria 2 z 4</p><div class="setprogress" aria-label="1 seria zapisana, aktualna seria 2 z 4"><span class="done"></span><span class="current"></span><span></span><span></span></div>'
 if variant=='cards': title='<div class="detailtitle" style="margin-bottom:0"><span class="thumb">'+exicon('squat')+'</span><div><h1>Przysiad<br>ze sztangą</h1><p class="sub">Trening A · ćwiczenie 1 z 4</p></div></div><div class="sectionhead"><h2>Seria 2 z 4</h2></div><div class="setprogress"><span class="done"></span><span class="current"></span><span></span><span></span></div>'
 if variant=='table': title='<p class="sub" style="margin-bottom:10px">Trening A · ćwiczenie 1 z 4</p><h1>Przysiad ze sztangą</h1><p class="sub" style="margin-bottom:14px">Wybierz serię</p><div class="rounds"><button class="saved" data-info="Seria 1: zapisano 6 powtórzeń × 90 kg." aria-label="Seria 1 zapisana">'+ico('check')+'</button><button class="on" aria-label="Seria 2 aktualna">2</button><button data-info="Szkic pokazuje zapis serii 2. Pozostałe serie obejrzysz w szczegółach.">3</button><button data-info="Szkic pokazuje zapis serii 2. Pozostałe serie obejrzysz w szczegółach.">4</button></div>'
 body=title+'<div class="goal"><small>Cel w planie · seria 2</small><strong>6 powt. × 90 kg</strong><p class="sub">75% 1RM · przerwa 2–3 min</p></div><p class="previous">Poprzednio: <strong>6 powt. × 87,5 kg</strong><br>Ten sam wariant · 14 października</p><form id="result"><div class="sectionhead"><h2>Twój wynik</h2><span>Wpisz wykonanie</span></div><div class="fields"><label>Powtórzenia<input name="reps" type="text" inputmode="numeric" autocomplete="off" placeholder="np. 6" aria-label="Wykonane powtórzenia"></label><label>Ciężar (kg)<input name="kg" type="text" inputmode="decimal" autocomplete="off" placeholder="np. 90" aria-label="Wykonany ciężar w kilogramach"></label></div><p class="helper">Cel nie jest zapisanym wynikiem.</p><button type="button" class="btn secondary" data-fill>Uzupełnij zgodnie z planem</button><div class="minoractions"><button type="button" class="textbtn" data-info="Dyktowanie w aplikacji pokazuje propozycję do zatwierdzenia.">'+ico('mic')+' Dyktuj</button><button type="button" class="textbtn" data-info="Pominięcie wymaga jawnego działania. Mock-up nie zapisuje wyników.">Pomiń serię</button></div><button class="btn" type="submit">Zapisz serię '+ico('check')+'</button><div class="save-status" role="status" id="save-status"></div></form>'
 if session=='b':
  body=body.replace('Trening A','Trening B').replace('Przysiad ze sztangą','Martwy ciąg').replace('Przysiad<br>ze sztangą','Martwy ciąg').replace('Seria 2 z 4','Seria 2 z 3').replace('6 powt. × 90 kg','5 powt. × 85 kg').replace('75% 1RM · przerwa 2–3 min','Rampa 80 / 85 / 90 kg · przerwa 3 min').replace('6 powt. × 87,5 kg','5 powt. × 82,5 kg').replace('np. 6','np. 5').replace('np. 90','np. 85').replace('data-fill','data-fill data-reps="5" data-kg="85"').replace('<span></span><span></span>','<span></span>').replace('<button data-info="Szkic pokazuje zapis serii 2. Pozostałe serie obejrzysz w szczegółach.">4</button>','')
 return body

script='''<script>
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-session'))parent.postMessage({t14:true,session:b.dataset.session,go:b.dataset.go},'*');else if(b.dataset.go){if(['plans','plan','detail','workout'].includes(b.dataset.go))parent.postMessage({t14:true,go:b.dataset.go,exercise:b.dataset.exercise},'*');else parent.postMessage({t14:true,info:'Makiety obejmują Plany, Podgląd, Szczegóły i Zapis serii. '+b.textContent.trim()+' pozostaje poza tym porównaniem.'},'*');}else if(b.hasAttribute('data-expand')){parent.postMessage({t14:true,go:b.getAttribute('aria-expanded')==='true'?'plan':'detail',exercise:b.dataset.exercise},'*');}else if(b.hasAttribute('data-fill')){document.querySelector('[name=reps]').value=b.dataset.reps||'6';document.querySelector('[name=kg]').value=b.dataset.kg||'90';document.getElementById('save-status').textContent='Uzupełniono pola. Wynik czeka na zapis.';}else if(b.dataset.info)parent.postMessage({t14:true,info:b.dataset.info},'*');});let f=document.getElementById('result');if(f)f.addEventListener('submit',e=>{e.preventDefault();let r=f.elements.reps.value.trim(),k=f.elements.kg.value.trim();document.getElementById('save-status').textContent=(!r||!k)?'Wpisz wykonane powtórzenia i ciężar.':'Symulacja: zapisano '+r+' powt. × '+k+' kg. Brak zapisu do bazy.';});
</script>'''
def frame(variant,screen,session='a',static=False,eidx=0):
 content={'plans':lambda:plans(variant,session),'plan':lambda:plan(variant,session),'detail':lambda:details(variant,session,eidx),'workout':lambda:workout(variant,session)}[screen]()
 foot='<div class="footer-action"><button class="btn" data-go="workout">'+ico('play')+' Rozpocznij trening '+session.upper()+'</button></div>' if screen=='plan' else ''
 back=screen in ['detail','workout'] and not (screen=='detail' and variant=='table')
 html='<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Forma — mock-up</title><style>'+css+'</style></head><body><div class="screen '+variant+'">'+header(back)+f'<main class="scroll"><div class="body">{content}</div></main>'+foot+nav('Trening' if screen=='workout' else 'Plany')+'</div>'+(script if not static else '')+'</body></html>'
 return html

css+='\n.focus .exercise-top{padding:8px 10px 4px;gap:10px}.focus .thumb{width:44px;height:44px}.focus .thumb .movement{width:42px;height:42px}.focus .metrics{padding:0 10px 8px 64px;gap:5px}.focus .metrics strong{font-size:14px}.focus .metrics small{font-size:10px}.focus .exercise{margin-bottom:8px}.focus .ename strong{font-size:15px}.focus .body:has(.plan-version),.table .body:has(.plan-version){padding-top:12px}.focus .plan-version,.table .plan-version{display:none}.focus .body:has(.plan-version) .headline,.table .body:has(.plan-version) .headline{min-height:34px}.focus .body:has(.plan-version) .headline h1,.table .body:has(.plan-version) .headline h1{font-size:24px}.focus .body:has(.plan-version) .tabs,.table .body:has(.plan-version) .tabs{margin:8px 0 10px}.focus .body:has(.plan-version) .sectionhead,.table .body:has(.plan-version) .sectionhead{margin:12px 0 8px}.focus .plan-count,.table .plan-count{margin-bottom:10px!important;font-size:12px}.table .exercise-top{padding-top:12px}.table .metrics{padding-bottom:12px}.table .tablehead{padding-top:8px}.facts .compactvalue{font-size:17px;line-height:1.3}.inline-detail .series td,.inline-detail .series th{font-size:12px}.movement{color:var(--forest)}\n'
for v in ['focus','table','cards']:
 (root/f'.impeccable/mocks/decision/{v}.html').write_text(frame(v,'plan',static=True))
frames={f'{v}:{s}:{d}:{i}':frame(v,s,d,eidx=i) for v in ['focus','table','cards'] for s in ['plans','plan','detail','workout'] for d in ['a','b'] for i in (range(4) if s=='detail' else [0])}
# Pełna galeria zawiera dane i wszystkie ekrany; nie wykonuje żadnego żądania sieciowego.
gallery='''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Forma · warianty UI</title><style>
:root{font-family:Arial,Helvetica,sans-serif;color:#1c2420;background:#e9ede7;font-size:14px}*{box-sizing:border-box}body{margin:0}button{font:inherit;cursor:pointer;color:inherit}button:focus-visible,a:focus-visible{outline:3px solid #467d27;outline-offset:3px}header.board{padding:28px 36px 20px;background:#f8faf5;border-bottom:1px solid #d2dbce;display:flex;align-items:center;gap:32px;justify-content:space-between}.board h1{font-size:25px;letter-spacing:-.035em;margin:0 0 6px}.board p{font-size:13px;line-height:1.5;color:#556259;margin:0;max-width:780px}.badge{white-space:nowrap;padding:8px 12px;border:1px solid #c6d1bf;border-radius:8px;font-size:12px;font-weight:700;color:#47603f}.controls{padding:16px 36px;background:#f8faf5;display:flex;gap:14px;align-items:center;flex-wrap:wrap;border-bottom:1px solid #d2dbce}.seg{display:flex;gap:3px;background:#e9eee4;padding:4px;border-radius:10px;flex-wrap:wrap}.seg button{background:none;border:0;min-height:40px;padding:8px 15px;border-radius:7px;font-weight:700;font-size:13px;color:#556259}.seg .on{background:#183b31;color:white}.grow{flex:1}.hint{font-size:12px;color:#556259;line-height:1.4}.stage{display:grid;grid-template-columns:repeat(3,minmax(300px,390px));gap:26px;justify-content:center;padding:28px 30px 32px;overflow:auto;align-items:start}.stage.single{grid-template-columns:390px}.variant h2{font-size:20px;margin:0 0 8px;letter-spacing:-.025em;display:flex;gap:12px;align-items:center}.letter{width:28px;height:28px;border-radius:7px;display:grid;place-items:center;background:#183b31;color:white;font-size:14px;flex:none}.variant p{font-size:13px;color:#556259;line-height:1.5;margin:0;min-height:44px}.phone{border:1px solid #9cae97;border-radius:22px;overflow:hidden;background:#f6f7f2;margin:14px 0 16px;width:100%;height:846px}.phone iframe{width:100%;height:844px;display:block;border:0;background:#f6f7f2}.tradeoff{margin:0 0 14px!important;font-size:12px!important;min-height:36px!important}.tradeoff strong{color:#1c2420}.choice{min-height:44px;width:100%;border:1px solid #95a68c;background:#f8faf5;color:#183b31;border-radius:10px;font-weight:700;padding:10px}.choice:hover{background:#d7f26d}.notes{padding:28px 36px 36px;border-top:1px solid #cad4c4;background:#f8faf5;display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:36px}.notes h2{font-size:18px;margin:0 0 10px}.notes p,.notes li{font-size:13px;color:#556259;line-height:1.6}.notes ul{padding-left:18px;margin:0}.notes p{margin:0}.notes a{color:#183b31;text-underline-offset:3px}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#183b31;color:white;padding:14px 20px;border-radius:12px;font-size:13px;max-width:600px;z-index:5;line-height:1.5}.toast[hidden]{display:none}.chosen{padding:14px 36px;background:#d7f26d;color:#183b31;font-size:14px;border-bottom:1px solid #b4c970;display:flex;justify-content:space-between;align-items:center;gap:16px}.chosen[hidden]{display:none}.chosen button{background:none;border:0;text-decoration:underline;min-height:40px}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:1050px){.stage{justify-content:start;grid-template-columns:repeat(3,360px);padding:20px}.stage.single{justify-content:center;grid-template-columns:minmax(300px,390px)}header.board{padding:22px 20px}.controls{padding:14px 20px}.notes{grid-template-columns:1fr;padding:24px 20px;gap:24px}.badge{display:none}}@media(max-width:440px){.stage{grid-template-columns:repeat(3,calc(100vw - 32px));padding:16px;gap:16px}.stage.single{grid-template-columns:minmax(0,1fr)}.controls{gap:10px;padding:12px 16px}.seg button{padding:8px 10px}.board h1{font-size:23px}.hint{display:none}.phone{border-radius:16px}}
</style></head><body>
<header class="board"><div><h1>Forma. Trzy sposoby na czytelny trening.</h1><p>Porównaj te same ćwiczenia i parametry w różnych układach. Przełącz ekrany, otwórz ćwiczenie lub sprawdź formularz serii. Wszystkie dane są syntetyczne.</p></div><span class="badge">Mock-upy do wyboru · 18.10.2026</span></header>
<div class="controls"><div class="seg" role="group" aria-label="Wybór widoku"><button class="on" data-view="all">Porównaj A / B / C</button><button data-view="focus">A · Rytm</button><button data-view="table">B · Zestawienie</button><button data-view="cards">C · Karty</button></div><div class="grow"></div><span class="hint">Zmieniasz wyłącznie makiety.<br>Żadnych zapisów w aplikacji.</span></div>
<div class="controls"><div class="seg" role="group" aria-label="Porównywany ekran"><button data-screen="plans">1. Plany</button><button class="on" data-screen="plan">2. Podgląd</button><button data-screen="detail">3. Szczegóły</button><button data-screen="workout">4. Zapis serii</button></div><button class="choice" style="width:auto;margin-left:auto" id="reset">Wróć do początku</button></div>
<div class="chosen" hidden id="chosen"><span></span><button id="clear">Wyczyść wybór</button></div>
<main class="stage" id="stage"></main>
<section class="notes"><div><h2>Co poprawiamy</h2><ul><li>Serie, ciężar i przerwa mają stałe, rozpoznawalne miejsca.</li><li>Symbol konkretnego ruchu ułatwia rozpoznanie ćwiczenia. Nazwa zawsze pozostaje widoczna.</li><li>Rozwinięcie rozdziela serie, wskazówki i źródło.</li><li>Wpisany wynik jest oddzielony od planowanego celu.</li></ul></div><div><h2>Co warto sprawdzić</h2><p>Przełącz na trening B: zobacz rampę 80 → 90 kg, brak 1RM oraz ćwiczenie na czas. W A zwróć uwagę na kilogramy na rękę i opcjonalną trzecią serię. Ikony to propozycje oznaczeń, nie instruktaż techniki.</p></div><div><h2>Twoja decyzja</h2><p>Wybierz układ albo wskaż połączenie, np. „lista A + szczegóły B”. Przycisk pod wariantem zaznacza preferencję w tej karcie; przekaż ją w chacie. Następny krok to dopracowanie wybranego kierunku. Te mock-upy nie zmieniają aplikacji.</p></div></section>
<div id="toast" class="toast" role="status" hidden></div>
<script>
const FRAMES=__FRAMES__;
const variants=[{id:'focus',letter:'A',name:'Rytm',desc:'Krótka lista ćwiczeń. Szczegóły na osobnym ekranie, z prostym powrotem do planu.',tradeoff:'Więcej miejsca na treść; przejście do szczegółów otwiera kolejny ekran.'},{id:'table',letter:'B',name:'Zestawienie',desc:'Parametry w stałych kolumnach. Wszystkie serie rozwijają się bez opuszczania listy.',tradeoff:'Najwięcej treści naraz; długie nazwy i nietypowe cele potrzebują więcej wierszy.'},{id:'cards',letter:'C',name:'Karty',desc:'Większe symbole ćwiczeń. Serie, obciążenie i przerwy mają własną przestrzeń.',tradeoff:'Najmocniejsze rozdzielenie informacji; więcej przewijania listy.'}];let screen='plan',session='a',view='all',exerciseIndex=0,chosen=null,timer;const stage=document.getElementById('stage');
function render(){stage.classList.toggle('single',view!=='all');stage.innerHTML='';variants.filter(v=>view==='all'||v.id===view).forEach(v=>{let section=document.createElement('section');section.className='variant';section.innerHTML='<h2><span class="letter">'+v.letter+'</span>'+v.name+'</h2><p>'+v.desc+'</p><div class="phone"><iframe sandbox="allow-scripts allow-forms" title="Wariant '+v.letter+' '+v.name+' — '+screen+'"></iframe></div><p class="tradeoff"><strong>Kompromis:</strong> '+v.tradeoff+'</p><button class="choice" data-choose="'+v.id+'">'+(chosen===v.id?'Zaznaczono '+v.letter:'Wybieram '+v.letter)+'</button>';section.querySelector('iframe').srcdoc=FRAMES[v.id+':'+screen+':'+session+':'+(screen==='detail'?exerciseIndex:0)];stage.appendChild(section)});document.querySelectorAll('[data-screen]').forEach(b=>{b.classList.toggle('on',b.dataset.screen===screen);b.setAttribute('aria-pressed',b.dataset.screen===screen)});document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('on',b.dataset.view===view);b.setAttribute('aria-pressed',b.dataset.view===view)})}
function info(t){let el=document.getElementById('toast');el.textContent=t;el.hidden=false;clearTimeout(timer);timer=setTimeout(()=>el.hidden=true,6500)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.screen){screen=b.dataset.screen;exerciseIndex=0;render()}if(b.dataset.view){view=b.dataset.view;render()}if(b.dataset.choose){chosen=b.dataset.choose;let v=variants.find(v=>v.id===chosen);document.getElementById('chosen').hidden=false;document.querySelector('#chosen span').textContent='Preferencja: '+v.letter+' · '+v.name+'. Napisz w chacie, co wybierasz lub co łączymy.';render()}if(b.id==='clear'){chosen=null;document.getElementById('chosen').hidden=true;render()}if(b.id==='reset'){screen='plan';session='a';view='all';exerciseIndex=0;render()}});
window.addEventListener('message',e=>{if(![...document.querySelectorAll('iframe')].some(f=>f.contentWindow===e.source)||!e.data?.t14)return;if(e.data.info){info(e.data.info);return}if(e.data.session)session=e.data.session;if(e.data.go){if(e.data.exercise!==undefined)exerciseIndex=Number(e.data.exercise)||0;screen=e.data.go}render()});render();
</script></body></html>'''
gallery=gallery.replace('__FRAMES__',json.dumps(frames,ensure_ascii=False).replace('</script>','<\\/script>'))
(out/'t14-mockupy.html').write_text(gallery)
print('Created gallery:',len(gallery),'characters; 42 embedded states; 3 first-view sketches')
